import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    Optimized model: fuse Sigmoid + Scaling + ResidualAdd after GEMM into a custom AscendC kernel.
    """
    def __init__(self, input_size, hidden_size, scaling_factor):
        super().__init__()
        self.gemm = torch.nn.Linear(input_size, hidden_size)
        self.scaling_factor = scaling_factor

    def forward(self, x):
        y = self.gemm(x)  # GEMM (nn.Linear)
        s_full = torch.full_like(y, self.scaling_factor)
        return custom_ops_lib.gemm_sigmoid_scaling_residual_add_custom(y, s_full)
